SELECT gen_random_uuid()::text, 'formula', '$M_r = \frac{1}{2\zeta\sqrt{1 - \zeta^2}}$', 'Resonant Peak and Frequency', '$M_r = \frac{1}{2\zeta\sqrt{1 - \zeta^2}},\qquad \omega_r = \omega_n\sqrt{1 - 2\zeta^2}\quad (\zeta < 0.707)$', NULL, 'The peak of a second-order system''s closed-loop frequency response.', '[{"symbol":"$\\zeta$","meaning":"damping ratio","unit":null},{"symbol":"$\\omega_n$","meaning":"natural frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'No peak at all for ζ ≥ 0.707. M_r of 1.1–1.5 is a common design target.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'bode plots' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE'
