SELECT gen_random_uuid()::text, 'formula', '$\omega_B = \omega_n\sqrt{1 - 2\zeta^2 + \sqrt{\ldots}}$', 'Bandwidth of a Second-Order System', '$\omega_B = \omega_n\sqrt{1 - 2\zeta^2 + \sqrt{4\zeta^4 - 4\zeta^2 + 2}}$', '$\text{rad/s}$', 'The frequency where the closed-loop response falls 3 dB below its DC value.', '[{"symbol":"$\\zeta$","meaning":"damping ratio","unit":null},{"symbol":"$\\omega_n$","meaning":"natural frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'At ζ = 0.707 the bandwidth equals ω_n. Wider bandwidth means a faster response.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'bode plots' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE'
