SELECT gen_random_uuid()::text, 'formula', '$\angle e^{-sT} = -\omega T$', 'Transport Delay Phase', '$e^{-sT}: |{\cdot}| = 1,\ \angle = -\omega T\ (\text{rad})$', '$\text{rad}$', 'A pure time delay adds phase lag that grows with frequency but leaves the gain unchanged.', '[{"symbol":"$T$","meaning":"dead time","unit":"$\\text{s}$"},{"symbol":"$\\omega$","meaning":"frequency","unit":"$\\text{rad/s}$"}]'::jsonb, 'It erodes phase margin: a delay of T costs ω_gc·T radians at crossover.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'gain and phase margins' AND s."active"), NULL, false, 'PENDING', now(), now()
