SELECT gen_random_uuid()::text, 'formula', '$G_c = K_p + \frac{K_i}{s} + K_ds$', 'PID Controller Transfer Function', '$G_c(s) = K_p + \frac{K_i}{s} + K_ds = K_p\left(1 + \frac{1}{T_is} + T_ds\right)$', NULL, 'The PID controller: present error, accumulated error, and the error''s rate of change.', '[{"symbol":"$K_p, K_i, K_d$","meaning":"proportional, integral and derivative gains","unit":null},{"symbol":"$T_i, T_d$","meaning":"integral and derivative times","unit":"$\\text{s}$"}]'::jsonb, 'Integral adds a pole at the origin (raises the type, removes step error); derivative adds a zero (adds damping).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'pid controllers' AND s."active"), NULL, true, 'PENDING', now(), now()
