SELECT gen_random_uuid()::text, 'formula', '$\sin\phi_m = \frac{1 - \alpha}{1 + \alpha}$', 'Lead Compensator', '$G_c = \frac{Ts + 1}{\alpha Ts + 1}\ (\alpha < 1):\quad \sin\phi_m = \frac{1 - \alpha}{1 + \alpha},\quad \omega_m = \frac{1}{T\sqrt\alpha}$', NULL, 'Adds phase near crossover to raise the phase margin and speed up the response.', '[{"symbol":"$\\alpha$","meaning":"pole/zero ratio, less than 1","unit":null},{"symbol":"$T$","meaning":"zero time constant","unit":"$\\text{s}$"}]'::jsonb, 'Place ω_m at the new gain crossover; the compensator''s gain there is 1/√α.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'compensators' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
