SELECT gen_random_uuid()::text, 'formula', '$G_c = \frac{Ts + 1}{\beta Ts + 1}\ (\beta > 1)$', 'Lag Compensator', '$G_c = \frac{Ts + 1}{\beta Ts + 1}\ (\beta > 1):\quad K_v \text{ raised by } \beta;\quad \frac1T \approx \frac{\omega_{gc}}{10}$', NULL, 'Raises low-frequency gain (cuts steady-state error) while barely touching the phase margin.', '[{"symbol":"$\\beta$","meaning":"pole/zero ratio, greater than 1","unit":null},{"symbol":"$T$","meaning":"zero time constant","unit":"$\\text{s}$"}]'::jsonb, 'Put the zero a decade below crossover so its phase lag does little harm; it slows the response slightly.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'compensators' AND s."active"), NULL, true, 'PENDING', now(), now()
