SELECT gen_random_uuid()::text, 'formula', '$G(s) = C(sI - A)^{-1}B + D$', 'Transfer Function from State Space', '$\dot{\mathbf{x}} = A\mathbf{x} + B\mathbf{u},\ \mathbf{y} = C\mathbf{x} + D\mathbf{u} \implies G(s) = C(sI - A)^{-1}B + D$', NULL, 'The transfer function hidden in a state-space model.', '[{"symbol":"$A, B, C, D$","meaning":"state, input, output and feedthrough matrices","unit":null}]'::jsonb, 'The poles are the eigenvalues of A: roots of det(sI − A) = 0.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'state space' AND s."active"), NULL, true, 'PENDING', now(), now()
