SELECT gen_random_uuid()::text, 'formula', '$\Phi(t) = \mathcal{L}^{-1}[(sI - A)^{-1}] = e^{At}$', 'State Transition Matrix', '$\Phi(t) = e^{At} = \mathcal{L}^{-1}[(sI - A)^{-1}],\qquad \mathbf{x}(t) = \Phi(t)\mathbf{x}(0) + \int_0^t\Phi(t - \tau)B\mathbf{u}(\tau)\,d\tau$', NULL, 'How the state evolves from its initial value, plus the input''s contribution.', '[{"symbol":"$A$","meaning":"state matrix","unit":null},{"symbol":"$\\mathbf{x}(0)$","meaning":"initial state","unit":null}]'::jsonb, 'Φ(0) = I, and dΦ/dt = AΦ.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'state space' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE'
