SELECT gen_random_uuid()::text, 'formula', '$\text{rank}[B\ AB \cdots] = n$', 'Controllability and Observability', '$\text{rank}[B\ \ AB\ \cdots\ A^{n-1}B] = n\ (\text{controllable}),\qquad \text{rank}\begin{bmatrix}C\\ CA\\ \vdots\\ CA^{n-1}\end{bmatrix} = n\ (\text{observable})$', NULL, 'Whether the input can steer every state, and whether the output reveals every state.', '[{"symbol":"$n$","meaning":"number of states","unit":null}]'::jsonb, 'A pole-zero cancellation in the transfer function means a state is uncontrollable or unobservable.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Feedback Control Systems' AND t."subject" = 'EE' AND s."normKey" = 'state space' AND s."active"), NULL, true, 'PENDING', now(), now()
